import { Router } from 'express'
import { z } from 'zod'

const router = Router()
export const db = { notes: [] }

const listQuery = z.object({ limit: z.coerce.number().int().min(1).max(100).default(20) })

router.get('/', (req, res) => {
  const parsed = listQuery.safeParse(req.query)
  if (!parsed.success) return res.status(400).json({ error: { code: 'invalid', message: 'Invalid query', issues: parsed.error.issues } })
  const mine = db.notes.filter((n) => n.userId === req.user.id).slice(0, parsed.data.limit)
  res.json({ data: mine })
})

export default router

