from pydantic import BaseModel

router = APIRouter(prefix="/orders", tags=["orders"])


class Order(BaseModel):
    id: int
    total: float


ORDERS = {1: Order(id=1, total=19.5), 2: Order(id=2, total=42.0)}


@router.get("", response_model=list[Order])
def list_orders():
